import React from "react";
import { useNavigate } from "react-router-dom";

const Hero = () => {
  const navigate = useNavigate();

  return (
    <section className="hero">

      <div className="container">

        {/* LEFT */}
        <div className="left">

          <p className="tag">WELCOME</p>

          <h1>
            I'm <span className="name">Swetha A</span>
          </h1>

          <h2 className="role">
            Full Stack Developer • System Builder • UI Thinker
          </h2>

          <p className="desc">
            I design structured systems and build meaningful applications
            where logic, design, and performance work together.
          </p>

          <div className="buttons">
            <button className="btn primary" onClick={() => navigate("/projects")}>
              Explore Projects →
            </button>
            <button className="btn secondary" onClick={() => navigate("/about")}>
              About Me →
            </button>
          </div>

        </div>

        {/* RIGHT ORBIT */}
        <div className="right">

          <div className="system">

            {/* OUTER RING */}
            <div className="ring ring1">
              <span className="particle p1"></span>
              <span className="particle p2"></span>
              <span className="particle p3"></span>
            </div>

            {/* INNER RING */}
            <div className="ring ring2">
              <span className="particle p4"></span>
              <span className="particle p5"></span>
            </div>

            {/* CENTER GIRL */}
            <div className="center">
              <img
                src="https://i.ibb.co/4f1R9Zc/female-avatar.png"
                alt="avatar"
              />
              <p>Swetha A</p>
            </div>

            {/* ORBIT TECH (RENAMED TO UNIQUE ROLES) */}
            <div className="orbit">

              <div className="node n1">Frontend Architect</div>
              <div className="node n2">Backend Engineer</div>
              <div className="node n3">API Designer</div>
              <div className="node n4">Database Strategist</div>
              <div className="node n5">UI Experience Builder</div>
              <div className="node n6">System Optimizer</div>

            </div>

          </div>

        </div>

      </div>

      <style>{`

        .hero {
          min-height: 100vh;
          display: flex;
          align-items: center;
          background: radial-gradient(circle at top, #0b1220, #050816);
          padding: 0 8%;
        }

        .container {
          display: grid;
          grid-template-columns: 1.2fr 1fr;
          gap: 60px;
          width: 100%;
          align-items: center;
        }

        /* LEFT */
        .tag {
          font-size: 12px;
          letter-spacing: 3px;
          color: #64748b;
        }

        h1 {
          font-size: 62px;
        }

        .name {
          color: #38BDF8;
        }

        .role {
          font-size: 20px;
          color: #94a3b8;
        }

        .desc {
          margin-top: 18px;
          font-size: 16px;
          color: #cbd5e1;
          line-height: 1.7;
          max-width: 520px;
        }

        .buttons {
          margin-top: 30px;
          display: flex;
          gap: 15px;
        }

        .btn {
          padding: 12px 22px;
          border-radius: 10px;
          font-weight: 600;
          border: 1px solid rgba(56,189,248,0.3);
          cursor: pointer;
        }

        .primary {
          background: #38BDF8;
          color: #0b1220;
        }

        .secondary {
          background: rgba(255,255,255,0.03);
          color: #38BDF8;
        }

        /* SYSTEM */
        .system {
          position: relative;
          width: 360px;
          height: 360px;
          margin: auto;
        }

        /* RINGS */
        .ring {
          position: absolute;
          border-radius: 50%;
        }

        .ring1 {
          width: 340px;
          height: 340px;
          top: 10px;
          left: 10px;
          border: 1px solid rgba(56,189,248,0.45);
          animation: spin 18s linear infinite;
        }

        .ring2 {
          width: 250px;
          height: 250px;
          top: 55px;
          left: 55px;
          border: 1px dashed rgba(56,189,248,0.3);
          animation: spinReverse 14s linear infinite;
        }

        /* 🌟 PARTICLES ON RING */
        .particle {
          position: absolute;
          width: 5px;
          height: 5px;
          background: #38BDF8;
          border-radius: 50%;
          box-shadow: 0 0 8px #38BDF8;
          opacity: 0.8;
        }

        .p1 { top: 20px; left: 60px; }
        .p2 { bottom: 30px; right: 40px; }
        .p3 { top: 120px; right: 10px; }
        .p4 { top: 40px; left: 120px; }
        .p5 { bottom: 60px; left: 80px; }

        @keyframes spin {
          100% { transform: rotate(360deg); }
        }

        @keyframes spinReverse {
          100% { transform: rotate(-360deg); }
        }

        /* CENTER GIRL FIXED */
        .center {
          position: absolute;
          top: 50%;
          left: 50%;
          transform: translate(-50%,-50%);
          text-align: center;
          z-index: 5;
        }

        .center img {
          width: 105px;
          height: 105px;
          border-radius: 50%;
          object-fit: cover;
          border: 2px solid rgba(56,189,248,0.6);
          box-shadow: 0 0 35px rgba(56,189,248,0.25);
        }

        .center p {
          font-size: 13px;
          color: #94a3b8;
          margin-top: 6px;
        }

        /* ORBIT TECH */
        .orbit {
          position: absolute;
          width: 100%;
          height: 100%;
          animation: spin 12s linear infinite;
        }

        .node {
          position: absolute;
          padding: 7px 12px;
          border-radius: 18px;
          background: rgba(255,255,255,0.04);
          border: 1px solid rgba(56,189,248,0.25);
          font-size: 11px;
          color: #cbd5e1;
          white-space: nowrap;
        }

        .n1 { top: 0; left: 50%; transform: translateX(-50%); }
        .n2 { top: 50%; right: 0; transform: translateY(-50%); }
        .n3 { bottom: 0; left: 50%; transform: translateX(-50%); }
        .n4 { top: 50%; left: 0; transform: translateY(-50%); }
        .n5 { top: 18%; right: 18%; }
        .n6 { bottom: 18%; left: 18%; }

        /* RESPONSIVE */
        @media (max-width: 900px) {
          .container {
            grid-template-columns: 1fr;
            text-align: center;
          }

          h1 {
            font-size: 42px;
          }

          .buttons {
            justify-content: center;
          }

          .system {
            margin-top: 40px;
          }
        }

      `}</style>

    </section>
  );
};

export default Hero;
